mapper.select:
SELECT c.* FROM chat_conversation c JOIN chat_conversation_member m ON m.conversation_id=c.conversation_id WHERE m.user_id=#{userId}
AND (COALESCE(c.last_message_at,c.created_at)<#{cursorTime} OR (COALESCE(c.last_message_at,c.created_at)=#{cursorTime} AND c.conversation_id<#{cursorId}))
ORDER BY COALESCE(c.last_message_at,c.created_at) DESC,c.conversation_id DESC LIMIT #{limit}
